function sum(arr) {
  let sum = 0;
  for (let item of arr) {
    (!isNaN(item)) sum += item;
  }
  return sum;
}

var grades = [80, 77, 88, 95, 68];

function getAvg(grades) {
  return grades.reduce(function (p, c) {
  return p + c;
}) / grades.length;
}

console.log(getAvg(grades))

